    .{ .id = 325, .name = "tf_ds_ring_word", .env = "TF_DS_RING_WORD", .group = "transport", .tab = "Transport", .kind = .flag, .unit = "", .min = null, .max = null, .default = "1", .default_text = "", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Generation word signalling", .doc = "On by default: each ring lane's data goes as a plain RDMA write and a 64-bit generation word is written after it to say it has arrived; the collecting kernel waits on those words. Set 0 for the flag-based arrival (the proxy publishes each lane's flag). The card's wait for the decode rings needs this on, with either arrival signal. Every node must agree.", .values = &.{}, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },
    .{ .id = 327, .name = "tf_ds_ring_word_signal", .env = "TF_DS_RING_WORD_SIGNAL", .group = "transport", .tab = "Transport", .kind = .choice, .unit = "", .min = null, .max = null, .default = "atomic", .default_text = "", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Generation word signal type", .doc = "How the generation word is sent: by default an RDMA atomic add, which the card executes only after the data writes are placed (the guaranteed arrival); word sends an 8-byte RDMA write instead. Every node must agree. A card without atomics: left unset, the rings send the write and say why in a warning; set to atomic, the start refuses by name.", .values = &.{ "word", "atomic" }, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },
    .{ .id = 921, .name = "tf_ds_roci_signal", .env = "TF_DS_ROCI_SIGNAL", .group = "transport", .tab = "Transport", .kind = .choice, .unit = "", .min = null, .max = null, .default = "atomic", .default_text = "", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Rocinante arrival signal", .doc = "How Rocinante tells a receiver a part has arrived: by default atomic (an RDMA atomic add, which InfiniBand orders after the data: the guaranteed arrival) or write (an 8-byte RDMA write of a generation word). A card without atomics: left unset, Rocinante sends the write and says why in a warning; set to atomic, the start refuses by name. Every node must agree.", .values = &.{ "write", "atomic" }, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },
    .{ .id = 931, .name = "tf_ds_roci_stagger_lanes", .env = "TF_DS_ROCI_STAGGER_LANES", .group = "transport", .tab = "Transport", .kind = .int, .unit = "passes", .min = 2.0, .max = 3.0, .default = "2", .default_text = "", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Passes in flight", .doc = "How many consecutive whole prompt passes run at once when the stagger is on: 2 (the pair) or 3 (a third pass on a third Rocinante lane). Measured on the four Sparks (a cold ~147K-token prompt): no gain at 3 (6,433 tok/s against 6,491-6,507 at 2, inside the noise), compute time a pass +2.7 % (three streams co-running stretch every kernel; idle unchanged at 39.7 ms), and about 5.5 GiB less free memory a Spark: keep 2. Needs TF_DS_ROCI_STAGGER=1 and passes of at most 10,240 rows; a Spark under the memory floor refuses 3 by name. Replies unchanged.", .values = &.{}, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },
    .{ .id = 981, .name = "tf_ds_roci_xlog", .env = "TF_DS_ROCI_XLOG", .group = "transport", .tab = "Transport", .kind = .flag, .unit = "", .min = null, .max = null, .default = "0", .default_text = "", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Exchange log (capture matching)", .doc = "Diagnostics, log only: the decode ring's peers kernel records, for each exchange and peer, the sequence and, on the GPU's own clock, when the kernel started, when that peer's words were all in and when the copy-out ended (a ring of 8,192 records in device memory, 256 KiB); each rank writes roci-xlog-rank<R>.txt when its ring closes. Per rank, wait and copy-out are then exact (one clock), and captures from the four ranks pair on the sequence instead of by time. Costs a few stores, two clock reads and one block barrier on each exchange's copy-out when on, nothing when off. Replies unchanged.", .values = &.{}, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },
    .{ .id = 982, .name = "tf_ds_roci_xlog_dir", .env = "TF_DS_ROCI_XLOG_DIR", .group = "transport", .tab = "Transport", .kind = .text, .unit = "", .min = null, .max = null, .default = "", .default_text = "the folder's log directory ($HOME/.cache/dsv41-tensorfold/logs)", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Exchange log folder", .doc = "Where TF_DS_ROCI_XLOG writes each rank's roci-xlog-rank<R>.txt when the ring closes; unset: the folder's log directory ($HOME/.cache/dsv41-tensorfold/logs). Created if missing. Only read with TF_DS_ROCI_XLOG=1.", .values = &.{}, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },
    .{ .id = 984, .name = "tf_ds_nact_log", .env = "TF_DS_NACT_LOG", .group = "decode", .tab = "Generation", .kind = .flag, .unit = "", .min = null, .max = null, .default = "0", .default_text = "", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Expert count log", .doc = "Diagnostics, log only: every decode launch's grouping appends a record (rows, distinct experts, how many this node owns, whether the shared expert is active) to a 4,096-record device ring, written to nact-rank<R>.txt every 256th call and at close: what a launch's gate/up and down weight bytes are, which no other counter keeps. Off: no launch and no copy. Replies unchanged.", .values = &.{}, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },
    .{ .id = 985, .name = "tf_ds_nact_dir", .env = "TF_DS_NACT_DIR", .group = "decode", .tab = "Generation", .kind = .text, .unit = "", .min = null, .max = null, .default = "", .default_text = "the folder's log directory ($HOME/.cache/dsv41-tensorfold/logs)", .check = .unchecked, .apply = .R, .secret = false, .hidden = false, .who = &.{.admin}, .label = "Expert count log folder", .doc = "Where TF_DS_NACT_LOG writes nact-rank<R>.txt; unset: the folder's log directory ($HOME/.cache/dsv41-tensorfold/logs). Created if missing. Only read with TF_DS_NACT_LOG=1.", .values = &.{}, .env_override = false, .out_changes = false, .now_ok = true, .agent = null, .requires = &.{}, .cost = &.{} },

